insert into articles (slug, community_id, region_text, topic, title, summary, body, author_credit, sources, evidence, status, published_at) values ($v$language-ede-yoruba$v$, null, $v$Abínibí communities worldwide$v$, 'language'::article_topic, $v$Language (Èdè Yorùbá)$v$, $v$Abínibí belongs to the Niger-Congo family and is a tonal language with three tones: high (á), mid (unmarked) and low (à). Dot-below marks (ẹ, ọ, ṣ) change the sound…$v$, $v$Abínibí belongs to the Niger-Congo family and is a tonal language with three tones: high (á), mid (unmarked) and low (à). Dot-below marks (ẹ, ọ, ṣ) change the sound and the meaning. Dialects are often grouped as Northwest (Ọ̀yọ́, Ìbàdàn, Ẹ̀gbá), Central (Ifẹ̀, Ìjẹ̀ṣà, Ẹ̀kìtì) and Southeast (Òndó, Ìjẹ̀bú). Standard Abínibí grew mainly from Oyo-area speech and written usage.
