insert into articles (slug, community_id, region_text, topic, title, summary, body, author_credit, sources, evidence, status, published_at) values ($v$names-oruko$v$, null, $v$Abínibí communities worldwide$v$, 'names'::article_topic, $v$Names (Orúkọ)$v$, $v$A child is traditionally named at the naming ceremony (ìsọmọlórúkọ), commonly on the 7th day for girls, 8th for boys and 9th for twins. Names often carry meaning,…$v$, $v$A child is traditionally named at the naming ceremony (ìsọmọlórúkọ), commonly on the 7th day for girls, 8th for boys and 9th for twins. Names often carry meaning, family history and praise.
insert into articles (slug, community_id, region_text, topic, title, summary, body, author_credit, sources, evidence, status, published_at) values ($v$belief-esin$v$, null, $v$Abínibí communities worldwide$v$, 'spirituality'::article_topic, $v$Belief (Ẹ̀sìn)$v$, $v$Traditional belief centres on Olódùmarè, the supreme being, and the òrìṣà, who relate to nature, society and human experience. Many Abínibí today are Christian or…$v$, $v$Traditional belief centres on Olódùmarè, the supreme being, and the òrìṣà, who relate to nature, society and human experience. Many Abínibí today are Christian or Muslim, and traditional practice continues alongside both.
