-- Publishes the pilot content taken from the supplied Ilẹ̀ Abínibí Atlas prototype.
-- Safe to run more than once (existing rows are skipped). Everything is marked published as requested;
-- evidence labels are the prototype's own, and entries still need source citations and community review.
alter table communities add column if not exists region_group text;
drop view if exists communities_public;
create view communities_public as
  select id, slug, preferred_name, kind, country, admin_area,
         case when coord_sensitive then null else lat end as lat, case when coord_sensitive then null else lng end as lng,
         coord_source, coord_precision, coord_verified, summary, body, evidence, last_reviewed_at, region_group
  from communities where status = 'published';
revoke all on communities_public from public, anon, authenticated;
grant select on communities_public to anon, authenticated;

on conflict (slug) do nothing;



